
#include "main.h"
#include <stdint.h>
#include <string.h>

// HAL handles generated by STM32CubeMX
extern I2C_HandleTypeDef hi2c1;
extern ADC_HandleTypeDef hadc1;

// =====================================
// CONFIGURATION
// =====================================

#define NUM_MAGNETS       4
#define NUM_SENSORS       4

#define MAGNET_CONTROL    0x01
#define SENSOR_REQUEST    0x02

// Magnet GPIO pins (configure in CubeMX)
GPIO_TypeDef* MAGNET_PORTS[NUM_MAGNETS] = {
    MAGNET_1_GPIO_Port,
    MAGNET_2_GPIO_Port,
    MAGNET_3_GPIO_Port,
    MAGNET_4_GPIO_Port
};

const uint16_t MAGNET_PINS[NUM_MAGNETS] = {
    MAGNET_1_Pin,
    MAGNET_2_Pin,
    MAGNET_3_Pin,
    MAGNET_4_Pin
};

// ADC channels for four Hall sensors
const uint32_t SENSOR_CHANNELS[NUM_SENSORS] = {
    ADC_CHANNEL_0,
    ADC_CHANNEL_1,
    ADC_CHANNEL_2,
    ADC_CHANNEL_3
};

// =====================================
// GLOBAL VARIABLES
// =====================================

// Sensor readings
volatile uint16_t sensor_values[NUM_SENSORS] = {0};

// I2C receive buffer
uint8_t rx_buffer[3];

// I2C transmit buffer
uint8_t tx_buffer[NUM_SENSORS * 2];

// Command processing variables
volatile uint8_t command_ready = 0;
volatile uint8_t received_magnet = 0;
volatile uint8_t received_state = 0;


// =====================================
// FUNCTION PROTOTYPES
// =====================================

void Read_All_Sensors(void);
void Update_Sensor_Buffer(void);
void Set_Local_Magnet(uint8_t magnet,
                      uint8_t state);
void Process_Command(void);


// =====================================
// MAIN
// =====================================

int main(void)
{
    HAL_Init();
    SystemClock_Config();

    MX_GPIO_Init();
    MX_ADC1_Init();
    MX_I2C1_Init();

    // Initialize all magnets OFF
    for (uint8_t i = 0; i < NUM_MAGNETS; i++)
    {
        HAL_GPIO_WritePin(
            MAGNET_PORTS[i],
            MAGNET_PINS[i],
            GPIO_PIN_RESET
        );
    }

    // Start I2C slave receive interrupt
    HAL_I2C_Slave_Receive_IT(
        &hi2c1,
        rx_buffer,
        sizeof(rx_buffer)
    );

    while (1)
    {
        // --------------------------------
        // LOOP 1: MAGNET COMMAND PROCESSING
        // --------------------------------

        if (command_ready)
        {
            Process_Command();
        }

        // --------------------------------
        // LOOP 2: CONTINUOUS SENSOR POLLING
        // --------------------------------

        Read_All_Sensors();

        // Prepare data for I2C transmission
        Update_Sensor_Buffer();
    }
}


// =====================================
// MAGNET GPIO CONTROL
// =====================================

void Set_Local_Magnet(uint8_t magnet,
                      uint8_t state)
{
    if (magnet >= NUM_MAGNETS || state > 1)
    {
        return;
    }

    HAL_GPIO_WritePin(
        MAGNET_PORTS[magnet],
        MAGNET_PINS[magnet],
        state ? GPIO_PIN_SET : GPIO_PIN_RESET
    );
}


// =====================================
// PROCESS MAGNET COMMAND
// =====================================

void Process_Command(void)
{
    uint8_t magnet;
    uint8_t state;

    __disable_irq();

    magnet = received_magnet;
    state = received_state;
    command_ready = 0;

    __enable_irq();

    Set_Local_Magnet(magnet, state);
}


// =====================================
// READ ALL HALL SENSORS
// =====================================

void Read_All_Sensors(void)
{
    ADC_ChannelConfTypeDef sConfig = {0};

    for (uint8_t i = 0; i < NUM_SENSORS; i++)
    {
        sConfig.Channel = SENSOR_CHANNELS[i];
        sConfig.Rank = ADC_REGULAR_RANK_1;
        sConfig.SamplingTime = ADC_SAMPLETIME_84CYCLES;

        if (HAL_ADC_ConfigChannel(
                &hadc1,
                &sConfig) != HAL_OK)
        {
            continue;
        }

        if (HAL_ADC_Start(&hadc1) != HAL_OK)
        {
            continue;
        }

        if (HAL_ADC_PollForConversion(
                &hadc1, 10) == HAL_OK)
        {
            sensor_values[i] =
                HAL_ADC_GetValue(&hadc1);
        }

        HAL_ADC_Stop(&hadc1);
    }
}


// =====================================
// PREPARE SENSOR DATA FOR I2C
// =====================================

void Update_Sensor_Buffer(void)
{
    for (uint8_t i = 0; i < NUM_SENSORS; i++)
    {
        uint16_t value = sensor_values[i];

        // High byte
        tx_buffer[i * 2] =
            (uint8_t)(value >> 8);

        // Low byte
        tx_buffer[i * 2 + 1] =
            (uint8_t)(value & 0xFF);
    }
}


// =====================================
// I2C RECEIVE COMPLETE CALLBACK
// =====================================

void HAL_I2C_SlaveRxCpltCallback(
    I2C_HandleTypeDef *hi2c)
{
    if (hi2c->Instance == I2C1)
    {
        // Decode received command
        if (rx_buffer[0] == MAGNET_CONTROL)
        {
            received_magnet = rx_buffer[1];
            received_state = rx_buffer[2];

            command_ready = 1;
        }

        // Re-enable I2C receive interrupt
        HAL_I2C_Slave_Receive_IT(
            &hi2c1,
            rx_buffer,
            sizeof(rx_buffer)
        );
    }
}
